      function renderCommunityFeedTable(posts=[]){const elements=communityFeedElements(),rows=posts.filter(post=>post.status!=='DELETED');elements.table.querySelector('tbody').replaceChildren(...rows.map(post=>{const row=document.createElement('tr');for(const value of [post.title,post.visibility,post.status,post.visibility==='PUBLIC'?Object.keys(post.public_metrics||{}).join(', ')||'geen':'verborgen']){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}return row}));elements.table.hidden=!rows.length;elements.tableEmpty.hidden=Boolean(rows.length);elements.public.textContent=String(rows.filter(post=>post.visibility==='PUBLIC').length);elements.private.textContent=String(rows.filter(post=>post.visibility==='PRIVATE').length);}
      async function prepareCommunityFeed(){const elements=communityFeedElements();elements.loading.hidden=false;elements.error.hidden=true;elements.status.textContent='loading';const suffix=Date.now(),email=`synthetic-community-${suffix}@example.test`;try{await apiCall('/api/v1/users',{method:'POST',body:JSON.stringify({email,display_name:'Synthetic Community'})});const session=await apiCall('/api/v1/sessions',{method:'POST',body:JSON.stringify({email,ttl_seconds:900})});communityFeedContext={token:session.token};setCommunityFeedReady();}catch(error){setCommunityFeedError(error);}}
      async function publishCommunityFeed(event){event.preventDefault();const elements=communityFeedElements();if(!communityFeedContext){setCommunityFeedError(new Error('Bereid eerst de synthetische fixture voor.'));return}elements.error.hidden=true;try{const visibility=document.getElementById('community-feed-visibility').value,title=document.getElementById('community-feed-title').value,body=document.getElementById('community-feed-body').value,result=await apiCall('/api/v1/community/posts',{method:'POST',headers:authHeadersFor(communityFeedContext.token),body:JSON.stringify({visibility,title,body,public_metrics:{allocation_percent:62.5,return_percent:4.2}})});communityFeedContext.postId=result.id;elements.status.textContent=`${result.status.toLowerCase()} · server moderated`;elements.result.textContent=`${result.visibility} · ${result.status} · post aangemaakt`;elements.empty.hidden=true;elements.evidence.textContent=`${result.calculation_version} · ${result.source} · private data redacted`;elements.traceId.textContent=result.trace_id||'—';elements.correlationId.textContent=result.correlation_id||'—';renderCommunityFeedTable([result]);}catch(error){setCommunityFeedError(error);}}
