      async function deleteCommunityFeed(){if(!communityFeedContext?.postId){setCommunityFeedError(new Error('Publiceer eerst een post.'));return}try{const result=await apiCall(`/api/v1/community/posts/${communityFeedContext.postId}/delete`,{method:'POST',headers:authHeadersFor(communityFeedContext.token)}),elements=communityFeedElements();elements.status.textContent='deleted · tombstone';elements.evidence.textContent=`${result.calculation_version} · ${result.audit_action} · physical ledger untouched`;elements.traceId.textContent=result.trace_id||'—';elements.correlationId.textContent=result.correlation_id||'—';elements.empty.hidden=false;elements.table.hidden=true;}catch(error){setCommunityFeedError(error);}}
      async function exportCommunityFeed(){if(!communityFeedContext){setCommunityFeedError(new Error('Bereid eerst de synthetische fixture voor.'));return}try{const result=await apiCall('/api/v1/community/export',{headers:authHeadersFor(communityFeedContext.token)}),elements=communityFeedElements();elements.result.textContent=`exported · ${result.posts.length} posts · community-export-v1`;elements.exportStatus.textContent='uitgevoerd';elements.evidence.textContent=`${result.source} · ${result.calculation_version} · owner-scoped`;elements.traceId.textContent=result.trace_id||'—';elements.correlationId.textContent=result.correlation_id||'—';}catch(error){setCommunityFeedError(error);}}
      document.getElementById('prepare-community-feed').addEventListener('click',()=>prepareCommunityFeed().catch(error=>setCommunityFeedError(error)));document.getElementById('community-feed-form').addEventListener('submit',publishCommunityFeed);document.getElementById('community-feed-moderate').addEventListener('click',()=>moderateCommunityFeed().catch(error=>setCommunityFeedError(error)));document.getElementById('community-feed-delete').addEventListener('click',()=>deleteCommunityFeed().catch(error=>setCommunityFeedError(error)));document.getElementById('community-feed-export').addEventListener('click',()=>exportCommunityFeed().catch(error=>setCommunityFeedError(error)));
    

